// function extractData(response)
// Agar response null: "No response"
// Agar response.ok nahi: "Request failed"
// Agar response.data nahi: "No data"
// Warna response.data return karo

solution:
function extractData(response) {
  if (!response) return "No response"
  if (!response.ok) return "Request failed"
  if (!response.data) return "No data"
  return response.data
}
